// TldStable -- transplanted into Assembly-CSharp by PatchV4.
//
// Compiled separately (mscorlib only) so that its IL is generated by csc rather than
// hand-emitted, then copied into the target module by Cecil. `Log` is NOT transplanted:
// the patcher redirects calls to it onto UnityEngine.Debug.LogError(string), built from
// the target module's existing UnityEngine.Debug type reference, so no new assembly
// reference is introduced.
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

internal static class TldStable
{
    // Exists only so the patcher/verifier can detect "already patched".
    public static void Marker()
    {
    }

    // Write obj to path atomically: serialise to path+".tmp", flush to disk, then
    // replace the real file (keeping a .bak). Any failure leaves the previous file
    // intact, removes the temp file and never throws at the caller.
    public static void SaveAtomic(string path, object obj)
    {
        string temp = path + ".tmp";
        bool committed = false;
        try
        {
            using (FileStream stream = new FileStream(temp, FileMode.Create, FileAccess.Write, FileShare.None))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                formatter.Serialize(stream, obj);
                stream.Flush(true);
            }
            if (File.Exists(path))
            {
                File.Replace(temp, path, path + ".bak");
            }
            else
            {
                File.Move(temp, path);
            }
            committed = true;
            AfterCommitted(path, obj);
        }
        catch (Exception error)
        {
            // Never let logging turn a swallowed save failure into a thrown one.
            try
            {
                Log("[TldStable] Atomic save failed for " + path + ": " + error.Message);
            }
            catch (Exception)
            {
            }
        }
        finally
        {
            if (!committed)
            {
                try
                {
                    if (File.Exists(temp))
                    {
                        File.Delete(temp);
                    }
                }
                catch (Exception)
                {
                }
            }
        }
    }

    private static void Log(string message)
    {
        // Replaced with UnityEngine.Debug.LogError(string) during the transplant.
    }

    private static void AfterCommitted(string path, object savedObject)
    {
        // Redirected to the multiplayer persistence callback by the patcher.
    }
}
